INSERT INTO community_posts(
  id,author_id,topic_id,title,body,locale,is_official,published_at,updated_at,created_at
) VALUES
  ('official-001','seed-admin','campus','新生報到前要先確認哪些資料','請先確認入學通知、護照姓名、學號、系所與報到日期。若資料不一致，請先聯繫學校國際事務窗口，避免到校後無法完成報到。','zh-Hant',1,'2026-10-12T01:00:00.000Z','2026-10-12T01:00:00.000Z','2026-10-12T01:00:00.000Z'),
  ('official-002','seed-admin','life','全民健康保險什麼時候可以加入','一般外籍學生在台連續居留滿一定期間後，可依規定加入全民健康保險。實際資格與日期請以健保署和學校承辦單位公告為準。','zh-Hant',1,'2026-10-12T01:01:00.000Z','2026-10-12T01:01:00.000Z','2026-10-12T01:01:00.000Z'),
  ('official-003','seed-admin','life','健保卡遺失後可以怎麼補辦','健保卡遺失時，可先確認是否能使用健保快易通或到郵局、健保署服務據點申請補發。補發方式與費用可能調整，請查閱最新官方資訊。','zh-Hant',1,'2026-10-12T01:02:00.000Z','2026-10-12T01:02:00.000Z','2026-10-12T01:02:00.000Z'),
  ('official-004','seed-admin','life','居留證到期前要注意什麼','請留意居留證效期，建議提早準備護照、在學證明、住宿或地址資料等文件。實際申請期限與文件清單請以移民署最新公告為準。','zh-Hant',1,'2026-10-12T01:03:00.000Z','2026-10-12T01:03:00.000Z','2026-10-12T01:03:00.000Z'),
  ('official-005','seed-admin','life','居留證地址變更提醒','如果搬家或宿舍異動，請確認是否需要在期限內辦理居留地址變更。逾期可能產生罰則，請以移民署規定為準。','zh-Hant',1,'2026-10-12T01:04:00.000Z','2026-10-12T01:04:00.000Z','2026-10-12T01:04:00.000Z'),
  ('official-006','seed-admin','campus','申請在學證明的常見用途','在學證明常用於居留、保險、銀行開戶或其他行政申請。不同單位可能要求紙本或英文版本，送件前請先確認格式。','zh-Hant',1,'2026-10-12T01:05:00.000Z','2026-10-12T01:05:00.000Z','2026-10-12T01:05:00.000Z'),
  ('official-007','seed-admin','campus','學生證遺失後先做這三件事','學生證遺失時，請先確認校內掛失流程、補發費用與領取時間。如果學生證同時具交通或門禁功能，也要留意是否需要另外停用。','zh-Hant',1,'2026-10-12T01:06:00.000Z','2026-10-12T01:06:00.000Z','2026-10-12T01:06:00.000Z'),
  ('official-008','seed-admin','campus','選課前請先看課程語言與限制','選課時請確認授課語言、先修條件、名額限制與加退選期限。若不確定學分是否承認，建議先詢問系辦或交換計畫窗口。','zh-Hant',1,'2026-10-12T01:07:00.000Z','2026-10-12T01:07:00.000Z','2026-10-12T01:07:00.000Z'),
  ('official-009','seed-admin','campus','請假申請需要保留證明文件','病假、事假或公假可能需要不同證明文件。請先閱讀課程與學校規定，並在期限內送出申請。','zh-Hant',1,'2026-10-12T01:08:00.000Z','2026-10-12T01:08:00.000Z','2026-10-12T01:08:00.000Z'),
  ('official-010','seed-admin','life','開立銀行帳戶前可以準備什麼','常見準備資料包含護照、居留證、學生證、在學證明、印章或台灣手機號碼。各銀行要求不同，請先向分行確認。','zh-Hant',1,'2026-10-12T01:09:00.000Z','2026-10-12T01:09:00.000Z','2026-10-12T01:09:00.000Z'),
  ('official-011','seed-admin','life','手機門號申辦前的注意事項','申辦門號前請確認合約期限、月租費、違約金、網路流量與身分文件要求。短期交換生可比較預付卡與月租方案。','zh-Hant',1,'2026-10-12T01:10:00.000Z','2026-10-12T01:10:00.000Z','2026-10-12T01:10:00.000Z'),
  ('official-012','seed-admin','life','租屋前先確認契約與押金','簽約前請確認租期、押金、電費算法、退租條件與是否可報稅或登記地址。若看不懂契約，建議請可信任的人協助閱讀。','zh-Hant',1,'2026-10-12T01:11:00.000Z','2026-10-12T01:11:00.000Z','2026-10-12T01:11:00.000Z'),
  ('official-013','seed-admin','life','垃圾分類與倒垃圾時間提醒','台灣多數地區需要依規定分類垃圾、資源回收與廚餘。不同城市和宿舍規則不同，請以所在地公告為準。','zh-Hant',1,'2026-10-12T01:12:00.000Z','2026-10-12T01:12:00.000Z','2026-10-12T01:12:00.000Z'),
  ('official-014','seed-admin','culture','課堂上寄信給老師的小提醒','寄信給老師時，建議寫清楚課程名稱、姓名、學號與問題重點。語氣保持禮貌，並預留老師回覆時間。','zh-Hant',1,'2026-10-12T01:13:00.000Z','2026-10-12T01:13:00.000Z','2026-10-12T01:13:00.000Z'),
  ('official-015','seed-admin','culture','小組報告溝通可以先約定分工','小組合作時，建議一開始就確認交件時間、每個人的負責範圍與聯絡方式。若溝通卡住，可以請助教或老師協助釐清。','zh-Hant',1,'2026-10-12T01:14:00.000Z','2026-10-12T01:14:00.000Z','2026-10-12T01:14:00.000Z'),
  ('official-016','seed-admin','campus','圖書館借書與空間使用提醒','使用圖書館前可先確認借閱期限、續借規則、討論室預約方式與飲食限制。不同校區規定可能不同。','zh-Hant',1,'2026-10-12T01:15:00.000Z','2026-10-12T01:15:00.000Z','2026-10-12T01:15:00.000Z'),
  ('official-017','seed-admin','campus','校園 Wi Fi 連不上怎麼辦','請先確認帳號格式、密碼是否更新，以及是否需要安裝憑證。若仍無法連線，可記下錯誤畫面向資訊服務單位詢問。','zh-Hant',1,'2026-10-12T01:16:00.000Z','2026-10-12T01:16:00.000Z','2026-10-12T01:16:00.000Z'),
  ('official-018','seed-admin','life','打工前請先確認工作許可','外籍學生在台工作通常需要符合資格並取得工作許可。開始工作前請確認核准期間、工時限制與雇主資訊。','zh-Hant',1,'2026-10-12T01:17:00.000Z','2026-10-12T01:17:00.000Z','2026-10-12T01:17:00.000Z'),
  ('official-019','seed-admin','life','緊急狀況可以先記下重要電話','建議先保存學校校安窗口、宿舍管理、警消與所在地醫療院所電話。遇到緊急狀況時，先確保人身安全再求助。','zh-Hant',1,'2026-10-12T01:18:00.000Z','2026-10-12T01:18:00.000Z','2026-10-12T01:18:00.000Z'),
  ('official-020','seed-admin','culture','文化差異討論請避免直接下結論','不同學生的經驗可能不一樣。分享文化觀察時，請描述情境與自己的感受，避免把單一經驗說成所有人都一樣。','zh-Hant',1,'2026-10-12T01:19:00.000Z','2026-10-12T01:19:00.000Z','2026-10-12T01:19:00.000Z');

COMMIT;
